import Card from '../components/Card';

const milestones = [
  { title: 'Week 1', description: 'Finish core DBMS and OS fundamentals', active: true },
  { title: 'Week 2', description: 'Complete networking concepts and sample problems', active: true },
  { title: 'Week 3', description: 'Build a mini project for software engineering workflow', active: false },
  { title: 'Week 4', description: 'Review and take the certification readiness quiz', active: false },
];

export default function RoadmapPage() {
  return (
    <div className="space-y-8">
      <Card title="AI Roadmap" description="A dynamic timeline showing the most important milestones for your learning journey.">
        <div className="space-y-6">
          {milestones.map((item, index) => (
            <div key={item.title} className="flex gap-5">
              <div className="flex flex-col items-center">
                <div className={`h-4 w-4 rounded-full ${item.active ? 'bg-teal-400' : 'bg-slate-400 dark:bg-slate-600'}`} />
                {index < milestones.length - 1 && <div className="h-full w-px bg-slate-300 dark:bg-slate-600" />}
              </div>
              <div className="rounded-3xl border border-slate-800 bg-slate-950/90 p-5 flex-1">
                <h3 className="text-xl font-semibold text-white">{item.title}</h3>
                <p className="mt-2 text-slate-400">{item.description}</p>
              </div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}
